import{_ as o,h as l,i as e,c as i,v as r,p as s,x as t,m as A,e as d,S as h}from"./chunks/framework.Dvtg8yj2.js";const D=JSON.parse('{"title":"伪标注大规模语音预训练","description":"","frontmatter":{"title":"伪标注大规模语音预训练","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-asr-pseudo-label.md","filePath":"llm/qwen3-asr-pseudo-label.md","lastUpdated":1788454257000}'),p={name:"llm/qwen3-asr-pseudo-label.md"};function E(m,a,c,u,T,_){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="伪标注大规模语音预训练" tabindex="-1">伪标注大规模语音预训练 <a class="header-anchor" href="#伪标注大规模语音预训练" aria-label="Permalink to &quot;伪标注大规模语音预训练&quot;">​</a></h1><div class="epigraph"><p>AuT 预训练使用约四千万小时伪标注识别数据，其中以中文和英文为主，从而在动态注意力窗口下得到稳定的音频表示。</p><footer>—— Qwen Team, Qwen3-ASR Technical Report, arXiv:2601.21337</footer></div><p>有标注语音按「小时 × 人工」涨，覆盖不了噪声、方言、歌声和长尾语言。Qwen3-ASR 的第一段训练不幻想四千万小时人工转写，而是：<strong>大规模无标（或弱标）语音 → 教师模型打伪标签 → 学生 AuT 按 AED 学</strong>。这是家族质量的底盘，后面的 Omni 三万亿 token 与 ASR SFT / RL 都站在这段表示上。本篇写伪标注如何进入 AuT、教师噪声如何不把学生钉死，以及它与 Whisper 的弱监督、ForcedAligner 的 MFA 伪时间戳有何不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AED 编码器要从频谱预测出能被交叉注意力对齐的序列。监督信号是文字。公开带标库以千小时计，方言和歌声更少。若只用带标库，12.5 Hz 表示会过拟合朗读腔，动态 1s–8s 窗也见不到足够的短窗/长窗组合。无标语音在互联网与产品日志里按数量级更多，但没有字。中间路是伪标注：教师先写字，学生当真理来学。问题变成教师从哪来、错标如何不坍缩成教师的复制品、以及四千万小时如何在中英主导的同时仍给 52 语种留出接口。</p><p>Whisper（Radford 等，2022）已经证明大规模弱监督（网络来源的音字对、过滤后当训练数据）可以训出稳健 AED。Qwen3-ASR 的表述更窄：AuT 阶段明确是 <strong>pseudo-labeled ASR data</strong>，约 \\(4\\times 10^7\\) 小时，中英为主。这不是把 Whisper 的配方重写一遍，而是把伪标数量级写进 LALM 编码器的前置条件。</p><h3 id="伪标是文字-不是频谱重构" tabindex="-1">伪标是文字，不是频谱重构 <a class="header-anchor" href="#伪标是文字-不是频谱重构" aria-label="Permalink to &quot;伪标是文字，不是频谱重构&quot;">​</a></h3><p>学生损失是识别交叉熵（AED），不是波形或 Fbank 重建。教师错一个专名，学生会把错误声学–文字对写进 12.5 Hz 几何。过滤、置信度、多教师投票因此属于系统，即使报告未逐项展开配方。写「四千万小时」时，应把它读成<strong>经过教师处理后的监督小时数</strong>，不是原始波形库存的毛时长。</p><p><span class="marginnote">Omni 预训练的 3T token 是多模态混合，不是又四千万小时 ASR。两段不要加在一起报「训练了多少小时语音」。AuT 伪标管声学编码器；Omni 管把该编码器接到 Qwen3 世界知识上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三段里的第一段" tabindex="-1">三段里的第一段 <a class="header-anchor" href="#三段里的第一段" aria-label="Permalink to &quot;三段里的第一段&quot;">​</a></h3><p>报告的训练链是：(1) AuT 伪标 AED 预训练；(2) 与 Qwen3-Omni 相同的多模态预训练；(3) 较小的多语 SFT，含非语音、流式增强与热词；(4) 约 5 万句上的 GSPO RL。伪标注只在 (1) 以「约 40 million hours」出现。SFT 明确与预训练语料不相交，避免评测泄漏，也避免学生永远只见教师的句子风格。(1) 的目标是：动态窗下仍稳定的通用音频表示，而不是最终字幕风格。</p><h3 id="教师–学生闭环" tabindex="-1">教师–学生闭环 <a class="header-anchor" href="#教师–学生闭环" aria-label="Permalink to &quot;教师–学生闭环&quot;">​</a></h3><p>抽象地写：</p> \\[\\mathcal{D}=\\{(x,\\hat{y})\\},\\qquad \\hat{y}=f_{\\mathrm{teacher}}(x),\\qquad \\min_\\theta \\mathcal{L}_{\\mathrm{AED}}(f_\\theta(x),\\hat{y}). \\]<p>\\(x\\) 是波形 / Fbank，\\(f_\\theta\\) 是 AuT。教师可以是上一迭代的识别器、专用多语 ASR、或过滤后的弱字幕。报告不把教师架构当作贡献点；系统要点是<strong>无标语音必须先变成字，才能进 AED</strong>。迭代伪标（学生变教师再打一遍）可以抬质量，也会放大偏见：中英教师更准，长尾语种的 \\(\\hat{y}\\) 更噪，四千万小时里中英为主会进一步加强。SFT 用不相交的多语真标（相对更小）做风格与覆盖校正，RL 再用难例补鲁棒性。伪标负责规模，真标与 RL 负责校准。</p>',16)),(e(),s(h,null,{default:t(()=>[d(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20UN%5B%22%E5%A4%A7%E8%A7%84%E6%A8%A1%E6%97%A0%E6%A0%87%E8%AF%AD%E9%9F%B3%22%5D%20--%3E%20TCH%5B%22%E6%95%99%E5%B8%88%E6%A8%A1%E5%9E%8B%E6%89%93%E4%BC%AA%E6%A0%87%E7%AD%BE%22%5D%0A%20%20TCH%20--%3E%20AED%5B%22AuT%20%E6%8C%89%20AED%20%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20AED%20--%3E%20OMNI%5B%22Omni%20%E5%A4%9A%E6%A8%A1%E6%80%81%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20OMNI%20--%3E%20SFT%5B%22%E5%B0%8F%E8%A7%84%E6%A8%A1%E5%A4%9A%E8%AF%AD%20SFT%22%5D%0A%20%20SFT%20--%3E%20RL%5B%22GSPO%20%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>ForcedAligner 另用 MFA 打<strong>伪时间戳</strong>，不是伪转写。两条伪标管道不要合并：一个监督字，一个监督 80 ms 索引。AuT 可以两边共用编码器初始化，损失与头不同。</p><p><span class="marginnote">伪标不会自动给出 LID 槽。教师若只出文字、不出语种，学生在 (1) 可能只学声学到字。(3) 的模板才把 <code>language</code> 槽钉上。把 52 语种全部归功于四千万小时，会夸大 (1) 的多语比例——报告写明该阶段中英为主。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>规模的作用是把 128 维 Fbank 与 8× 卷积在极其多样的信道上训成可线性分开的 12.5 Hz 轨迹：噪声、混响、音乐、口音成为同一表示空间里的可加扰动，而不是另一种任务。动态窗在大数据上才有统计：短窗、长窗的组合数随小时数涨，编码器才不会在推理换窗时崩。这是伪标与动态窗绑在一起的原因——窗是结构，小时数是让结构长出不变性的燃料。</p><h3 id="教师噪声为何没有完全传给-sota-数字" tabindex="-1">教师噪声为何没有完全传给 SOTA 数字 <a class="header-anchor" href="#教师噪声为何没有完全传给-sota-数字" aria-label="Permalink to &quot;教师噪声为何没有完全传给 SOTA 数字&quot;">​</a></h3><p>若学生容量大于教师且数据覆盖更广，学生可以平滑教师的随机错误，类似知识蒸馏里的温度与大数据。若教师有系统性偏见（某方言总写成普通话），大数据会把偏见变成几何里的主方向，SFT 只能局部扳。报告在内部方言与口音集上仍领先，说明 (3)(4) 与 Omni 的多语信号起了校正；但不能据此声称伪标无偏。机制上应把伪标看成<strong>高召回、有偏的监督</strong>，用后训练当偏置校正器。</p><p>Whisper 的弱监督常含网络字幕错位；他们靠过滤。Qwen3-ASR 把类似思想用在 LALM 编码器前置。差别是学生还要接到 Qwen3：伪标阶段若把表示训得只对小 AED 解码器友好、对 LM 前缀不友好，projector 后训练会很痛。因此 (1) 仍用 AED（AuT 自带解码器）先学「能对齐的声学」，(2) 再把同一编码器接到 LM。伪标不是直接训 LALM 生成，而是训编码器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>四千万小时不是可复现的开源包。外部复现应把数当数量级，把方法当「教师伪标 + AED」，不要伪造一份同等数据清单。中英主导意味着长尾语种的表示更多来自 (2)(3) 与相关语言的迁移；Fleurs 全 30 语上相对 Whisper 的差距，与伪标语言不平衡同方向，不应只用模型宽度解释。</p><p><span class="marginnote">不要用伪标去打时间戳再拿去训 ASR。时间伪标走 MFA → ForcedAligner；字伪标走教师 ASR → AuT。交叉使用会把 80 ms 索引误差写进识别损失，或把识别错字写进对齐格子。</span></p><p>另一边界：版权与日志数据。大规模语音的来源若含用户通话，伪标流程必须在系统外解决授权；技术报告给的是训练策略，不是数据许可证。工程上还要防教师崩溃：教师若在某类噪声上出重复 n-gram，学生会学会「幻觉循环」，RL 的 5 万句未必洗得掉。监控伪标的平均长度、重复率、语种直方图，应视为与 WER 同等的训练健康指标。</p><p>相对纯 CTC 自训练：CTC 伪标常配合过滤阈值与解码格子。AED / LALM 伪标的错误是整句替换，更难用帧置信度滤。家族用后续 SFT 不相交与 RL 难例，而不是在 (1) 写复杂的帧级过滤论文。复现时若只有 CTC 教师，要预期错误类型不同，不能假设同等小时数同等效果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AuT 用约四千万小时伪标注 AED 预训练，中英为主，撑起动态窗下的稳定表示。</li><li>伪标路径是无标语音经教师得字，再监督学生；不是频谱重构，也不是 Omni 的 3T token。</li><li>SFT 数据与预训练不相交，负责槽位、多语与风格；RL 再补难例。</li><li>时间戳伪标（MFA）是另一条管道，只服务 ForcedAligner。</li><li>规模校正不了系统性教师偏见；长尾语种质量不能单凭 52 与 40M 小时外推。</li><li>出处：Qwen Team, <em>Qwen3-ASR Technical Report</em>, arXiv:2601.21337；对照 Radford 等，Whisper，2022 的大规模弱监督；CTC 自训练为另一条伪标传统。</li></ul>',14))])}const b=o(p,[["render",E]]);export{D as __pageData,b as default};
